Script:
$ErrorActionPreference='Stop'
Set-Location 'F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$checks=Get-Content -LiteralPath 'artifacts/benchmark-queue/b128d839e2ad497591e55cf22eb9054e/result.json' -Raw|ConvertFrom-Json
if($checks.ExitCode -ne 0){Write-Output 'BEHAVIOR_GATE_FAILED';exit 2}
$directory='artifacts/relations-measurements/focused-native-r39'
$files=@('src/SomeEngine.ECS.Relations/IQueryRelationOutput.cs','src/SomeEngine.ECS.Relations/RelationQuery.cs','src/SomeEngine.Physics/CollisionPairBuffer.cs')
$pairPath=(Resolve-Path -LiteralPath $files[2]).Path
$text=[IO.File]::ReadAllText($pairPath).Replace('_pairWriteRanges','_pairRangesResource')
[IO.File]::WriteAllText($pairPath,$text,[Text.UTF8Encoding]::new($false))
git diff --check -- @files
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
git add -- @files
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
git commit -m 'Hold relation output values and build pair offsets in the parent'
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$source=(git rev-parse HEAD).Trim()
$record=[pscustomobject]@{SourceCommit=$source;ChangedFiles=$files;BehaviorQueueId=$checks.Id;BehaviorExitCode=$checks.ExitCode;TokenName='_pairRangesResource';PushExitCode=$null;PublishStartedAtUtc=$null;PublishFinishedAtUtc=$null;PublishExitCode=$null;SourceCheckExitCode=$null;Object=$null;Executable=$null}
try{
    git push
    $record.PushExitCode=$LASTEXITCODE
    if($record.PushExitCode -ne 0){exit $record.PushExitCode}
    $template=Get-Content -LiteralPath 'artifacts/benchmark-queue/8767f2f40a364863bfe35e8ce317be30/result.json' -Raw|ConvertFrom-Json
    [string[]]$publishArguments=@($template.Arguments|ForEach-Object{if($_.StartsWith('-p:SourceRevisionId=')){'-p:SourceRevisionId='+$source}else{$_}})
    $record.PublishStartedAtUtc=[DateTime]::UtcNow.ToString('O')
    Write-Output ('PUBLISH '+$template.Executable+' '+($publishArguments -join ' '))
    & $template.Executable @publishArguments
    $record.PublishExitCode=$LASTEXITCODE
    $record.PublishFinishedAtUtc=[DateTime]::UtcNow.ToString('O')
    if($record.PublishExitCode -ne 0){exit $record.PublishExitCode}
    $native='benchmarks/SomeEngine.ECS.Relations.Benchmarks/bin/Release/net10.0/win-x64/native-publish/SomeEngine.ECS.Relations.Benchmarks.exe'
    & $native --mode list --source $source|Out-Null
    $record.SourceCheckExitCode=$LASTEXITCODE
    if($record.SourceCheckExitCode -ne 0){exit $record.SourceCheckExitCode}
    $obj=Get-Item -LiteralPath 'benchmarks/SomeEngine.ECS.Relations.Benchmarks/obj/Release/net10.0/win-x64/native/SomeEngine.ECS.Relations.Benchmarks.obj'
    $exe=Get-Item -LiteralPath $native
    $record.Object=[pscustomobject]@{Path=$obj.FullName;LastWriteTimeUtc=$obj.LastWriteTimeUtc.ToString('O');Length=$obj.Length}
    $record.Executable=[pscustomobject]@{Path=$exe.FullName;LastWriteTimeUtc=$exe.LastWriteTimeUtc.ToString('O');Length=$exe.Length}
}
finally{
    $record|ConvertTo-Json -Depth 7|Set-Content -LiteralPath "$directory/source.json" -Encoding utf8
    Write-Output ('SOURCE_CHECK_PUBLISH '+($record|ConvertTo-Json -Depth 7 -Compress))
}
exit 0
